-- 036_grammar_reference_wave7_appendices_and_missing_questions.sql
--
-- Gramer Rehberi -- Madde 17 (Ekler) + eksik pratik sorularinin kapatilmasi.
--
-- BOLUM 1 -- Ekler: kitaptaki Eklerin (duzensiz fiiller, yazim kurallari,
-- kisaltmalar, fiil/sifat+edat kaliplari, Amerikan/Ingiliz Ingilizcesi
-- farklari, noktalama) SADECE genel/standart basliklarindan esinlenilerek,
-- 7 adet ozgun referans notu ayri grammar_topics satiri acmadan, ilgili
-- mevcut konularin rule_content_md alanina eklendi (UPDATE ... || ).
--
-- BOLUM 2 -- Eksik pratik sorulari: uygulamada "Bu konu icin henuz pratik
-- sorusu eklenmedi" uyarisi cikan 12 eski konu (2. dalgadan once eklenmis,
-- hic exam_questions'i olmayan konular) icin 2'ser ozgun soru yazildi (24
-- yeni soru). Artik TUM grammar_topics satirlarinin en az 1 pratik sorusu
-- var (dogrulandi: topics_without_q = 0).
--
-- ICERIK KAYNAGI VE TELIF NOTU: onceki migration'larla ayni ilke -- SADECE
-- standart dilbilgisi terminolojisi/basliklari kullanilmistir, tum metin
-- (kural notlari, sorular, aciklamalar) %100 ozgun yazilmistir.
--
-- Bu SQL, Supabase MCP apply_migration araciyla proje mrxeuxscyztpiuagsumh
-- uzerinde 2 parcada (appendices UPDATE, missing questions INSERT) zaten
-- uygulanmistir; bu dosya repo gecmisi icin ayniyla tekrar eder.

-- Madde 17: Ekler -- mevcut konulara referans notu ekleme (7 adet)
UPDATE grammar_topics SET rule_content_md = rule_content_md || '
' || '- **EK — Düzensiz Fiiller (Irregular Verbs):** İngilizcede çok sayıda fiil, past simple ve past participle (V2/V3) formlarını -ed eki almadan, kendine özgü bir şekilde oluşturur. Present Perfect ve Past Simple kurarken bu formları ezbere bilmek gerekir. En sık kullanılan bazı düzensiz fiiller (yalın hal — V2 — V3): be-was/were-been, begin-began-begun, break-broke-broken, bring-brought-brought, build-built-built, buy-bought-bought, catch-caught-caught, choose-chose-chosen, come-came-come, do-did-done, drink-drank-drunk, drive-drove-driven, eat-ate-eaten, fall-fell-fallen, feel-felt-felt, find-found-found, fly-flew-flown, forget-forgot-forgotten, get-got-got/gotten, give-gave-given, go-went-gone, have-had-had, hear-heard-heard, keep-kept-kept, know-knew-known, leave-left-left, lose-lost-lost, make-made-made, meet-met-met, pay-paid-paid, put-put-put, read-read-read, ring-rang-rung, run-ran-run, say-said-said, see-saw-seen, sell-sold-sold, send-sent-sent, sing-sang-sung, sit-sat-sat, speak-spoke-spoken, spend-spent-spent, swim-swam-swum, take-took-taken, teach-taught-taught, tell-told-told, think-thought-thought, understand-understood-understood, wake-woke-woken, wear-wore-worn, win-won-won, write-wrote-written.' WHERE slug = 'present-perfect-vs-past-simple';
UPDATE grammar_topics SET rule_content_md = rule_content_md || '
' || '- **EK — Kısaltılmış Yapılar (Contractions):** Günlük ve konuşma dilinde özne ile yardımcı fiil, ya da yardımcı fiil ile "not" kelimesi kısaltılarak birleştirilir. Yaygın kısaltmalar: I''m (I am), you''re (you are), he''s/she''s/it''s (he/she/it is), we''re (we are), they''re (they are), I''ve (I have), I''ll (I will), I''d (I would/had), isn''t (is not), aren''t (are not), wasn''t (was not), weren''t (were not), don''t (do not), doesn''t (does not), didn''t (did not), haven''t (have not), hasn''t (has not), hadn''t (had not), won''t (will not), wouldn''t (would not), can''t (cannot), couldn''t (could not), shouldn''t (should not), mustn''t (must not). Resmi/akademik yazıda ("essay", rapor) kısaltmalar genellikle TERCİH EDİLMEZ, açık form kullanılır; günlük konuşmada ve gayriresmi yazışmada kısaltmalar doğaldır.' WHERE slug = 'question-tags';
UPDATE grammar_topics SET rule_content_md = rule_content_md || '
' || '- **EK — Fiile -ing Eklenirken Yazım Kuralları:** (1) Sessiz "e" ile biten fiillerde "e" düşer: make→making, write→writing, have→having. (2) Tek heceli, tek sesli harfle biten ve tek ünsüzle biten fiillerde son ünsüz ikizlenir: run→running, sit→sitting, stop→stopping (ama fix→fixing, çünkü x tek harf sayılır ve ikizlenmez). (3) "ie" ile biten fiillerde "ie" → "y" olur: die→dying, lie→lying, tie→tying. (4) "ee", "oe", "ye" gibi çift sesli harfle bitenlerde normal şekilde -ing eklenir: see→seeing, agree→agreeing.' WHERE slug = 'present-simple-vs-continuous';
UPDATE grammar_topics SET rule_content_md = rule_content_md || '
' || '- **EK — Düzenli Fiillere -ed Eklenirken Yazım Kuralları:** (1) Fiil zaten "e" ile bitiyorsa sadece "-d" eklenir: like→liked, agree→agreed. (2) Tek heceli, tek sesli harfle biten ve tek ünsüzle biten fiillerde son ünsüz ikizlenir: stop→stopped, plan→planned (ama visit→visited, çünkü ikinci hece vurgulu değil). (3) Sessiz harften sonra "y" ile bitenlerde "y"→"i" olur ve "-ed" eklenir: study→studied, carry→carried (ama play→played, çünkü "y"den önce sesli harf var). Düzensiz fiiller için ayrı bir ek listesi mevcuttur (bkz. Present Perfect ve Past Simple Farkı konusu).' WHERE slug = 'past-simple-vs-continuous';
UPDATE grammar_topics SET rule_content_md = rule_content_md || '
' || '- **EK — Sık Kullanılan Fiil + Edat ve Sıfat + Edat Kalıpları:** Fiil + edat: listen TO, look AT/FOR, wait FOR, depend ON, believe IN, apologize FOR, congratulate sb ON, consist OF, deal WITH, insist ON, succeed IN, suffer FROM, worry ABOUT. Sıfat + edat: interested IN, afraid OF, good/bad AT, famous FOR, proud OF, responsible FOR, similar TO, different FROM, tired OF, satisfied WITH, aware OF, capable OF. Bu kalıplarda edat, fiilin/sıfatın anlamına göre SABİTTİR ve genellikle ezbere öğrenilmesi gerekir — Türkçedeki karşılığıyla birebir örtüşmeyebilir (ör. "interested in" Türkçede "-e ilgili" değil "ile ilgilenen" anlamındadır).' WHERE slug = 'dependent-prepositions';
UPDATE grammar_topics SET rule_content_md = rule_content_md || '
' || '- **EK — Amerikan ve İngiliz İngilizcesi Arasındaki Farklar:** Yazım: colour/color, favourite/favorite, centre/center, travelling/traveling, realise/realize. Kelime: flat/apartment, lorry/truck, holiday/vacation, lift/elevator, autumn/fall, rubbish/garbage, chemist''s/drugstore, mobile phone/cell phone, biscuit/cookie. YDS/YÖKDİL gibi sınavlarda genellikle İngiliz İngilizcesi esas alınır ama her iki varyantın da doğru kabul edildiği sorularla karşılaşılabilir; bir metin içinde tutarlı bir varyant kullanmak (ikisini karıştırmamak) yazma görevlerinde önemlidir.' WHERE slug = 'word-formation-collocations';
UPDATE grammar_topics SET rule_content_md = rule_content_md || '
' || '- **EK — Temel Noktalama ve Büyük Harf Kuralları:** (1) Bağlaçlarla (and, but, or, so, for, nor, yet) birleşen iki tam cümle arasına VİRGÜL konur: "I called her, but she didn''t answer." (2) Bir cümleyi ikiye bölebilecek iki bağımsız cümleyi bağlaç olmadan birleştirmek için NOKTALI VİRGÜL kullanılır: "It was raining; we stayed home." (3) Özel isimler, ülke/dil adları, ay ve gün isimleri ile cümlenin ilk harfi her zaman BÜYÜK HARFLE başlar: Turkey, Turkish, Monday, September. (4) "I" (ben) zamiri cümle içinde her zaman büyük harfle yazılır. Bu kurallar özellikle yazma (essay) bölümlerinde sık gözden kaçan hatalardandır.' WHERE slug = 'connectors-linking-words';
